import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_data_line(line: str) -> bool:
        s = line.strip()
        if not s:
            return False
        if s.upper() == "FOOTNOTE":
            return False
        return True

    start = 0
    while start < len(lines) and not is_data_line(lines[start]):
        start += 1

    if start >= len(lines):
        return {"columns": [], "rows": []}

    sample = "\n".join(lines[start:start + 20])
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=[',', ';', '\t', '|'])
    except Exception:
        dialect = csv.excel
        dialect.delimiter = ','
        dialect.quotechar = '"'
        dialect.doublequote = True
        dialect.skipinitialspace = False
        dialect.lineterminator = '\n'
        dialect.quoting = csv.QUOTE_MINIMAL

    reader = csv.reader(io.StringIO("\n".join(lines[start:])), dialect)
    rows: List[List[str]] = []
    for row in reader:
        if not row:
            continue
        if len(row) == 1 and row[0].strip().upper() == "FOOTNOTE":
            break
        rows.append([str(v) for v in row])

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    max_width = max([len(header)] + [len(r) for r in data_rows]) if data_rows else len(header)
    if len(header) < max_width:
        header = header + ["" for _ in range(max_width - len(header))]
    elif len(header) > max_width:
        max_width = len(header)
        data_rows = [r + ["" for _ in range(max_width - len(r))] if len(r) < max_width else r[:max_width] for r in data_rows]

    normalized_rows: List[List[str]] = []
    for r in data_rows:
        if len(r) < max_width:
            r = r + ["" for _ in range(max_width - len(r))]
        elif len(r) > max_width:
            r = r[:max_width]
        normalized_rows.append([str(v) for v in r])

    return {"columns": [str(c) for c in header], "rows": normalized_rows}
